inputs = ['byvyvx', 'vkehd', 'gvux', 'cge', 'fui']
outputs = ['iuayvyvx', 'vjwjxhiuahd', 'gvux', 'cgxhiua', 'fui']

print("Careful pattern matching:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"\n{i}: '{inp}' -> '{out}'")
        print(f"  Full match: {inp == out}")

        # Check if output starts with input + something
        if out.startswith(inp):
            print(f"  Output starts with input + {out[len(inp):]}")
        else:
            # Check prefixes
            for j in range(min(len(inp), len(out)), 0, -1):
                if inp[:j] == out[:j]:
                    print(f"  Common prefix of length {j}: '{inp[:j]}'")
                    break

            # Check suffixes  
            for j in range(min(len(inp), len(out)), 0, -1):
                if inp[-j:] == out[-j:]:
                    print(f"  Common suffix of length {j}: '{inp[-j:]}'")
                    break

        # Let's see the exact differences
        min_len = min(len(inp), len(out))
        for k in range(min_len):
            if inp[k] != out[k]:
                print(f"  First difference at position {k}: '{inp[k]}' -> '{out[k]}'")
                break
        else:
            if len(inp) != len(out):
                print(f"  Same up to length {min_len}, extra chars in output: '{out[min_len:]}'")

